#!/usr/bin/env -S uv run --script
# Synced from bootstrap: macos/tools/tailscale/tasks/upgrade-tailscale.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Upgrade Tailscale (mise-poured formula, runs as a root brew service)"
# MISE hide=true
# MISE dir="~"
# MISE tools={uv="latest", python="3.14"}

# The formula is mise's ([bootstrap.packages]); only the daemon goes through
# `brew services`, because tailscaled needs root for the utun interface and mise
# has no privileged services on macOS. The App Store build is sandboxed and
# cannot run the Tailscale SSH server, which is why the formula's daemon is used.

import fnmatch
import os
import shutil
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, os.path.expanduser("~/.config/mise/tasks/_scripts"))
import helpers  # noqa: E402


def run(*cmd):
  """Run the command. When it fails, stop the task with its code, as set -e
  does. A missing command gives 127, as in the shell."""
  sys.stdout.flush()
  try:
    rc = subprocess.run(cmd, check=False).returncode
  except FileNotFoundError:
    print(f"{cmd[0]}: command not found", file=sys.stderr, flush=True)
    sys.exit(127)
  if rc:
    sys.exit(128 - rc if rc < 0 else rc)


def quiet(*cmd):
  """Return the code of the command, with its output in /dev/null. A missing
  command gives 127."""
  try:
    return subprocess.run(cmd, check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode
  except FileNotFoundError:
    return 127


def main():
  helpers.print_header("Tailscale ...")

  # Check if tailscale is installed before attempting to upgrade
  if quiet("brew", "list", "--formulae", "tailscale") != 0:
    helpers.print_error("Tailscale formula is not installed. Skipping.")
    sys.exit(0)

  # No upgrade available: just make sure the service is running. Checked via the
  # process, not `brew services start` — under sudo that re-bootstraps the daemon
  # every time, which drops the tunnel for nothing.
  sys.stdout.flush()
  outdated = subprocess.run(
    ["brew", "outdated", "--formulae", "tailscale"], check=False, stdout=subprocess.PIPE, text=True
  ).stdout
  if not outdated.rstrip("\n"):
    if quiet("pgrep", "-x", "tailscaled") == 0:
      helpers.print_subheader("Tailscale is up to date and running.")
    else:
      helpers.print_subheader("Tailscale is up to date, starting the service ...")
      run("sudo", "brew", "services", "start", "tailscale")
    sys.exit(0)

  helpers.print_subheader("Stopping Tailscale service ...")
  run("sudo", "brew", "services", "stop", "tailscale")

  # The service runs as root, so its keg ends up root-owned and `brew cleanup`
  # cannot remove it. Hand the keg back to the user before upgrading.
  # Resolve the versioned keg from the binary symlink, e.g.
  # /opt/homebrew/Cellar/tailscale/1.102.4/bin/tailscale -> .../tailscale/1.102.4
  binary = shutil.which("tailscale")
  keg = os.path.dirname(os.path.dirname(os.path.realpath(binary))) if binary else "."
  if fnmatch.fnmatchcase(keg, "*/Cellar/tailscale/*"):
    helpers.print_subheader(f"Restoring ownership of {keg} ...")
    run("sudo", "chown", "-R", f"{os.environ.get('USER', '')}:staff", keg)
  else:
    helpers.print_warn("Cannot find the Tailscale keg: skipping the ownership step")

  helpers.print_subheader("Upgrading Tailscale ...")
  run("mise", "bootstrap", "packages", "upgrade", "brew:tailscale", "--yes")

  helpers.print_subheader("Cleaning up old Tailscale versions ...")
  run("sudo", "brew", "cleanup", "tailscale")

  helpers.print_subheader("Starting Tailscale service ...")
  run("sudo", "brew", "services", "start", "tailscale")


if __name__ == "__main__":
  main()
